function retryAfter(email, kind, cap) {
  const now = Math.floor(Date.now() / 3600000);
  const row = db.prepare('SELECT count,window FROM learning_limits WHERE key=?').get(`${kind}:${digest(email)}`);
  return row?.window===now && row.count>=cap ? Math.max(1,Math.ceil(((now+1)*3600000-Date.now())/1000)) : 0;
}

if (row?.window === now && row.count >= cap) {
  const message=kind==='review'?'本小时 AI 点评次数已用完；作业已保存，无需重复提交。':kind==='submit'?'本小时提交次数已用完，本次尚未提交。请保留草稿，稍后重试。':'本小时操作较多，请稍后继续。草稿仍会保留。';
  throw Object.assign(new Error(message),{status:429,code:kind==='review'?'review_rate_limited':'rate_limited',retryAfter:retryAfter(email,kind,cap)});
}

try { limit(email,'review',12); }
catch(error) {
  if(error.status!==429)throw error;
  return json({...view(row),saved:true,error:error.message,code:error.code,retryAfter:error.retryAfter},429,{'Retry-After':String(error.retryAfter)});
}
